head.script:
// 화면 리사이징

scwin.procJob;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gEmpNo = js_emp_no;
scwin.gAcptNo;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        await scwin.readLoginInfo();

        // fn_ShowButton();

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar4(edt_SDate, 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar4(edt_EDate, 2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name edt_SDate_OnLastChar
 * @description edt SDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_SDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(1); // if(시작일>종료일) 종료일=시작일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.edt_SDate_OnLastChar" });
    }
};

/**
 * @method
 * @name edt_EDate_OnLastChar
 * @description edt EDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_EDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(2); // if(시작일>종료일) 시작일=종료일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.edt_EDate_OnLastChar" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnFail
 * @description Grid On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnFail = async function() {
    try {
        await scwin.alert_error2(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.dts_Grid_OnFail" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await scwin.alert_error2(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_Grid.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Login_OnLoadCompleted
 * @description dts_Login 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Login_OnLoadCompleted = function(rowcount) {
    try {
        scwin.showButton(dts_Login.getCellData(1, "JOBTITL"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.dts_Login_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === 'DOC_TITLE') {
            if (scwin.gAcptNo !== '') {
                await $c.stf.openDisclViewer(scwin.gAcptNo, "R", "ULDSTF15460.xml");
            }
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF15460.xml", SCREN_PROCS_TP_CD_07, '');
        const file_name = "예약공시 내역";
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
        $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_IMMEDT_PUBL_onclick
 * @description 「즉시배포」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_IMMEDT_PUBL_onclick = async function() {
    try {
        await scwin.immedtApproval();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.btn_IMMEDT_PUBL_onclick" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15460.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15460.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readLoginInfo
 * @description read Login Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readLoginInfo = async function() {
    const sbmOptions = {
        id : "sbm_dts_Login",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_Login=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name immedtApproval
 * @description 즉시배포
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.immedtApproval = async function() {
    // 선택한 항목이 있는지 check
    if (await scwin.check() === true) {
        await scwin.setHeader();
        let k = 0;
        dts_UpdateList.setBroadcast(false);
        for (let i = 1; i <= dts_Grid.getRowCount(); i++) {
            if (dts_Grid.getCellData(i, "CHECK") === "T") {
                k++;
                dts_UpdateList.insertRow();
                dts_UpdateList.setCellData(k, "ACPT_NO", dts_Grid.getCellData(i, "ACPT_NO"));
                dts_UpdateList.setCellData(k, "EMP_NO", scwin.gEmpNo);
            }
        }
        dts_UpdateList.setBroadcast(true, true);
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + k + '건을 즉시배포'))) return;
        scwin.procJob = "예약공시 즉시배포";
        trs_save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/DisclosureApproval.do",
            ref : "dts_UpdateList",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_UpdateList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_UpdateList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    edt_EDate.setValue(vCurDate);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    rdo_APPROV_YN.setValue("");
};

/**
 * @method
 * @name showButton
 * @description show Button 처리
 * @param {*} sJobtitl sJobtitl
 * @returns {void}
 * @hidden N
 */
scwin.showButton = function(sJobtitl) {
    // alert(js_emp_no + "\n" + js_jobtitl + "\n" + sJobtitl);

    // 버튼 비활성화
    if (sJobtitl !== '40' && (sJobtitl === '09' || scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y')) {
        if (btn_IMMEDT_PUBL.getDisabled()) {
            btn_IMMEDT_PUBL.setBackgroundImage(btn_IMMEDT_PUBL.src.replace('_d.gif', '.gif'));
            btn_IMMEDT_PUBL.setDisabled(false);
        }
    } else {
        if (!btn_IMMEDT_PUBL.getDisabled()) {
            btn_IMMEDT_PUBL.setBackgroundImage(btn_IMMEDT_PUBL.src.replace('.gif', '_d.gif'));
            btn_IMMEDT_PUBL.setDisabled(true);
        }
    }
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};

/**
 * @method
 * @name check
 * @description check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check = async function() {
    let checkCnt = 0;
    for (let i = 1; i <= dts_Grid.getRowCount(); i++) {
        if (dts_Grid.getCellData(i, "CHECK") === "T") {
            checkCnt++;
        }
    }
    if (checkCnt <= 0) {
        await $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_Grid.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        for (let j = 0; j < errorCount; j++) {
            const sCode = dtsObj.SrvErrCode(USER_DEFINE[i], j);
            const sMsg = dtsObj.SrvErrMsg(USER_DEFINE[i], j);
            if (sCode === '0') {
                // '0' 임의로 떨군 INFO 메시지
                if (sMsg === "SESSION_CLOSED") {
                    // 로그아웃
                    $c.frame.path("/top").SystemClose();
                    await $c.win.alert("세션이 종료되었습니다. 다시 로그인해 주세요.");
                } else {
                    await $c.win.alert(sMsg);
                }
            } else {
                // 기존 에러 메시지
                const a_1 = sMsg.indexOf("{");
                const a_2 = sMsg.indexOf("*/");
                const a_3 = sMsg.indexOf("}");
                const t_1 = sMsg.substr(0, a_2 + 2);
                const t_2 = "\n......\n";
                const t_3 = sMsg.substr(a_3, sMsg.length - a_3);
                await $c.win.alert("[CODE: " + sCode + "] " + t_1 + t_2 + t_3);
            }
        }
    }
};
